def manhattan_dist(p1, p2):
    return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

def transform_cell(r, c, grid, min_color, other_colors):
    val = grid[r][c]
    if val == 0 or val != min_color:
        return val
    else:
        best_val = None
        best_dist = float('inf')
        for rr in range(h):
            for cc in range(w):
                if grid[rr][cc] != 0 and grid[rr][cc] != min_color:
                    dist = manhattan_dist((r,c), (rr,cc))
                    if dist < best_dist:
                        best_dist = dist
                        best_val = grid[rr][cc]
        return best_val if best_val else 0

