import os, json, re, math

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

demo_in_2 = G['Demo pair 2 input']
demo_out_2 = G['Demo pair 2 output']

def manhattan_dist(p1, p2):
    return abs(p1[0]-p2[0]) + abs(p1[1]-p2[1])

def find_nearest_color(r, c, grid):
    """Find what color min-cell (r,c) should become"""
    colors_pos = {}
    h, w = len(grid), len(grid[0])
    for rr in range(h):
        for cc in range(w):
            val = grid[rr][cc]
            if val != 0 and val == 1:  # skip 1s
                continue
            colors_pos.setdefault(val, []).append((rr, cc))

    best_val = None
    best_dist = float('inf')
    for val, positions in colors_pos.items():
        for pos in positions:
            dist = manhattan_dist((r,c), pos)
            if dist < best_dist:
                best_dist = dist
                best_val = val
            elif dist == best_dist and best_val is not None:
                # Tie-break: smallest color value wins
                pass  # Already set best_val, keep smaller

    return best_val

print("=== CHECKING NEAREST NON-MIN RULE FOR DEMO 2 ===")
all_correct = True
errors = []
for r in range(9):
    for c in range(9):
        inp_val = demo_in_2[r][c]
        out_val = demo_out_2[r][c]

        # We only care about cells that were originally 1 (min color)
        if inp_val == 1:
            expected = find_nearest_color(r, c, demo_in_2)
