import os, json, re

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

demo_in_2 = G['Demo pair 2 input']
demo_out_2 = G['Demo pair 2 output']

def find_components(grid, target_val):
    comps = []
    visited = set()
    h, w = len(grid), len(grid[0])
    for r in range(h):
        for c in range(w):
            if grid[r][c] == target_val and (r,c) not in visited:
                comp = set()
                queue = [(r,c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr,cc) in visited: continue
                    visited.add((cr,cc))
                    comp.add((cr,cc))
                    for dr,dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr,nc = cr+dr, cc+dc
                        if 0<=nr<h and 0<=nc<w and grid[nr][nc]==target_val and (nr,nc) not in visited:
                            queue.append((nr,nc))
                comps.append(comp)
    return comps

def get_centroid(cells):
    avg_r = sum(c[0] for c in cells) / len(cells)
    avg_c = sum(c[1] for c in cells) / len(cells)
    return (avg_r, avg_c)

