import os, json, re

d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
t = open(d+'/../../sessions/'+os.path.basename(d)+'.jsonl').read().replace('\\n', '\n')
G = {}
for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
    k, h, w = m[1], int(m[2]), int(m[3])
    rows = [r.split() for r in t[m.end():].split('\n')[:h]]
    if k not in G and all(len(r)==w and all(x.isdigit() for x in r) for r in rows):
        G[k] = [[int(x) for x in r] for r in rows]

demo_in_2 = G['Demo pair 2 input']
demo_out_2 = G['Demo pair 2 output']

def get_first_nonbg(r, c, grid, direction):
    """direction: 'up', 'down', 'left', 'right'"""
    sr, sc = r, c
    if direction == 'up':
        while sr > 0:
            sr -= 1
            val = grid[sr][c]
            if val != 0:
                return val
    elif direction == 'down':
        while sr < len(grid) - 1:
            sr += 1
            val = grid[sr][c]
            if val != 0:
                return val
    elif direction == 'left':
        while sc > 0:
            sc -= 1
            val = grid[r][sc]
            if val != 0:
                return val
    elif direction == 'right':
        while sc < len(grid[0]) - 1:
            sc += 1
            val = grid[r][sc]
            if val != 0:
                return val
    return None

print("=== PROJECTED NEIGHBORS FOR EACH 1-CELL ===")
comp_cells = [(1,1),(1,2),(1,3),(2,1),(2,3),(1,6),(2,6),(2,7),(5,2),(5,3),(6,3)]
for (r,c) in comp_cells:
    up = get_first_nonbg(r, c, demo_in_2, 'up')
    down = get_first_nonbg(r, c, demo_in_2, 'down')
    left = get_first_nonbg(r, c, demo_in_2, 'left')
