# Function to find all connected components of a given color (8-way connectivity)
def find_components(grid, target_color):
    rows = len(grid)
    cols = len(grid[0])
    visited = [[False] * cols for _ in range(rows)]
    components = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target_color and not visited[r][c]:
                # BFS with 8-way connectivity
                comp_cells = []
                queue = [(r, c)]
                visited[r][c] = True
                while queue:
                    curr_r, curr_c = queue.pop(0)
                    comp_cells.append((curr_r, curr_c))
                    for dr in [-1, 0, 1]:
                        for dc in [-1, 0, 1]:
                            if dr == 0 and dc == 0:
                                continue
                            nr, nc = curr_r + dr, curr_c + dc
                            if 0 <= nr < rows and 0 <= nc < cols:
                                if not visited[nr][nc] and grid[nr][nc] == target_color:
                                    visited[nr][nc] = True
                                    queue.append((nr, nc))
                components.append(comp_cells)
    return components

