# Function to get all NON-bg, NON-1 adjacent cells around a component
def get_neighbors_excluding_min(comp, grid):
    rows = len(grid)
    cols = len(grid[0])
    seen = set()
    neighbors = []
    for r, c in comp:
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                nr, nc = r + dr, c + dc
                if 0 <= nr < rows and 0 <= nc < cols:
                    val = grid[nr][nc]
                    if val != 0 and val != 1 and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        neighbors.append((val, nr, nc))
    return neighbors

# Apply the rule: For each component, find neighbors (excluding bg and min-color), 
# pick the MOST FREQUENT neighbor color
def predict_by_adjacency_rule(grid):
    comp_1s = find_components(grid, 1)
    predictions = {}
    for i, comp in enumerate(comp_1s):
        neighbors = get_neighbors_excluding_min(comp, grid)
        if neighbors:
            colors = [n[0] for n in neighbors]
            freq = Counter(colors)
            # Get most common, break ties by picking smallest color value
            most_common_colors = freq.most_common(1)[0]
            predicted = most_common_colors[0]
        else:
            # No neighbors? This shouldn't happen based on analysis
            predicted = None
        predictions[i] = (comp, predicted, neighbors)
    return predictions

