    # Score tuple: (has_row_sharing?, min_shared_row_or_infinity, has_col_sharing?, min_shared_col_or_infinity)
    # Higher scores win; then break ties by picking smaller color value

    for other_color in sorted(all_color_shapes.keys()):
        if other_color == exclude_color or other_color == 1:
            continue

        other_color_set = all_color_shapes[other_color]

        # Find shared rows
        comp_rows_obj = {r for r,c in comp}
        comp_cols_obj = {c for r,c in comp}

        shared_rows = comp_rows_obj.intersection({r for r,c in other_color_set})
        shared_cols = comp_cols_obj.intersection({c for r,c in other_color_set})

        num_rows_shared = len(shared_rows)
        num_cols_shared = len(shared_cols)

        if num_rows_shared > 0:
            min_shared_row = min(shared_rows)
            row_priority = 1  # Row sharing wins
        else:
            min_shared_row = float('inf')
            row_priority = 0

        if num_cols_shared > 0:
            min_shared_col = min(shared_cols)
            col_priority = 1
        else:
            min_shared_col = float('inf')
            col_priority = 0

        # Score: higher is better
        # Format: (priority_type, min_index_value)
        if num_rows_shared > 0:
            score = (row_priority, min_shared_row)
        elif num_cols_shared > 0:
            score = (col_priority, min_shared_col)
        else:
            # No sharing at all, pick smallest touching
            touching_count = sum(1 for r,c in comp for r_o,c_o in other_color_set if r==r_o or c==c_o)
            score = (-1, -touching_count)

        # Check if this color should be new best
        current_best_score = None
        if best_color is not None:
            current_best_score = score
        else:
            # Recalculate current best's score
            curr_comp_rows = {r for r,c in comp}
            curr_comp_cols = {c for r,c in comp}
            for bc in [best_color]:
