                elif len(cur_shared_cols) > 0:
                    cur_min_col = min(cur_shared_cols)
                    cur_score = (0, cur_min_col)
                else:
                    cur_touching = sum(1 for r,c in comp for r_o,c_o in bc_set if r==r_o or c==c_o)
